mapper.select:
SELECT upm.user_pay_management_code, upm.payroll_code, upm.company_code, upm.pay_period, upm.user_id, um.user_name, dm.dept_name, upm.pay_date as payrollDate, upm.salary, upm.bonus, upm.overtime_allowance AS overtime, upm.night_allowance AS night, upm.holiday_allowance AS holiday, upm.family_allowance AS family, upm.meal_allowance AS meal, upm.annual_leave_allowance AS annualLeave, upm.total_allowance AS totalAllowance, upm.total_payment AS totalPaymentAmount, upm.income_tax as incomeTax, upm.national_pension, upm.employment_insurance, upm.health_insurance, upm.long_time_care_insurance, upm.total_deduction AS totalDeductionAmount, upm.net_pay FROM tb_user_pay_management upm JOIN tb_user_master um ON upm.user_id = um.user_id JOIN tb_dept_master dm ON um.dept = dm.dept_code WHERE 1=1
AND dm.dept_code like '%' || #{dept} || '%'
AND um.user_name like '%' || #{userName} || '%'
AND upm.pay_period >= #{payPeriodStart}
AND upm.pay_period <= #{payPeriodEnd}
